def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            divider = ("row", r, grid[r][0])
            break
    if divider is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                divider = ("col", c, vals[0])
                break
    if divider is None:
        return [row[:] for row in grid]

    axis, d, line_color = divider
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != line_color]
    if not points:
        return [row[:] for row in grid]

    coords = [r if axis == "row" else c for r, c in points]
    lo, hi = min(coords), max(coords)

    if lo > d:
        shift = d + 1 - lo
        trail = hi + shift + 1
    elif hi < d:
        shift = d - 1 - hi
        trail = lo + shift - 1
    else:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r, c in points:
        out[r][c] = bg
    for r, c in points:
        nr = r + shift if axis == "row" else r
        nc = c + shift if axis == "col" else c
        out[nr][nc] = grid[r][c]

    if axis == "row" and 0 <= trail < h:
        out[trail] = [8] * w
    elif axis == "col" and 0 <= trail < w:
        for r in range(h):
            out[r][trail] = 8

    return out
